\set ON_ERROR_STOP on
create function pg_temp.check_it(label text,ok boolean) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.reject_it(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate in ('42601','42883','42P01','42703') then raise;end if;raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpected acceptance: %',label;end$$;
set role authenticated;
select set_config('test.actor','e2000000-0000-0000-0000-000000000001',false);
insert into operations_orders(id,branch_id,reference,requester,component,units,due_at,responsible) values('e5000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','PLAN-1','Centro sintético','PG',2,now()+interval '2 days','Equipo A');
select pg_temp.check_it('pedido inicia pendiente y con autor autenticado',(select status='PENDIENTE' and created_by=auth.uid() and revision=1 from operations_orders where reference='PLAN-1'));
select pg_temp.reject_it($q$update operations_orders set status='COMPLETADO' where reference='PLAN-1'$q$,'no se omiten etapas del pedido');
update operations_orders set status='EN_GESTION' where reference='PLAN-1';
select pg_temp.check_it('actualización incrementa revisión',(select revision=2 from operations_orders where reference='PLAN-1'));
select pg_temp.reject_it($q$update operations_orders set revision=1 where reference='PLAN-1'$q$,'revisión obsoleta rechazada');
select pg_temp.reject_it($q$update operations_orders set branch_id='e1000000-0000-0000-0000-000000000002' where reference='PLAN-1'$q$,'pedido no cambia de sucursal');
select pg_temp.reject_it($q$update operations_orders set status='CANCELADO' where reference='PLAN-1'$q$,'cancelación necesita motivo');
update operations_orders set status='LISTO' where reference='PLAN-1';update operations_orders set status='COMPLETADO' where reference='PLAN-1';
select pg_temp.reject_it($q$update operations_orders set units=9 where reference='PLAN-1'$q$,'pedido cerrado inmutable');
select pg_temp.check_it('auditoría de pedidos generada',(select count(*)>=4 from workflow_audit where table_name='operations_orders'));
select pg_temp.reject_it($q$insert into operations_orders(branch_id,reference,requester,component,units,due_at,responsible) values('e1000000-0000-0000-0000-000000000001','BAD','Centro','PG',0,now(),'A')$q$,'cantidad positiva obligatoria');
select pg_temp.reject_it($q$insert into operations_orders(branch_id,reference,requester,component,units,due_at,responsible) values('e1000000-0000-0000-0000-000000000002','OTHER','Centro','PG',1,now(),'A')$q$,'pedido fuera de sucursal rechazado');
select set_config('test.actor','e2000000-0000-0000-0000-000000000002',false);
select pg_temp.check_it('consulta permite leer pedido',(select count(*)=1 from operations_orders));
select pg_temp.reject_it($q$insert into operations_orders(branch_id,reference,requester,component,units,due_at,responsible) values('e1000000-0000-0000-0000-000000000001','NO-WRITE','Centro','PG',1,now(),'A')$q$,'consulta no crea pedidos');
select set_config('test.actor','e2000000-0000-0000-0000-000000000003',false);
select pg_temp.check_it('perfil inactivo no lee pedidos',(select count(*)=0 from operations_orders));
select pg_temp.reject_it($q$insert into operations_orders(branch_id,reference,requester,component,units,due_at,responsible) values('e1000000-0000-0000-0000-000000000001','INACTIVE','Centro','PG',1,now(),'A')$q$,'inactivo no modifica planificación');
select set_config('test.actor','e2000000-0000-0000-0000-000000000001',false);
select pg_temp.reject_it($q$insert into donor_visits(donor_id,branch_id,starts_at) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',((current_date+73)::text||' 09:00:00-04')::timestamptz)$q$,'83 días desde última donación rechazados en servidor');
insert into donor_visits(id,donor_id,branch_id,starts_at) values('e4000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',((current_date+74)::text||' 09:00:00-04')::timestamptz);
select pg_temp.check_it('cita a los 84 días exactos se guarda',(select count(*)=1 from donor_visits));
update donor_visits set starts_at=((current_date+90)::text||' 09:00:00-04')::timestamptz where id='e4000000-0000-0000-0000-000000000001';
select pg_temp.reject_it($q$insert into donor_visits(donor_id,branch_id,starts_at) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',now()+interval '95 days')$q$,'donante no recibe dos citas activas');
insert into donor_agenda_capacity(branch_id,slot_minutes,capacity) values('e1000000-0000-0000-0000-000000000001',30,1);
select pg_temp.reject_it($q$insert into donor_visits(donor_id,branch_id,starts_at) values('e3000000-0000-0000-0000-000000000003','e1000000-0000-0000-0000-000000000001',((current_date+90)::text||' 09:15:00-04')::timestamptz)$q$,'franja llena impide sobrecupo');
insert into donor_visits(id,donor_id,branch_id,starts_at) values('e4000000-0000-0000-0000-000000000003','e3000000-0000-0000-0000-000000000003','e1000000-0000-0000-0000-000000000001',((current_date+90)::text||' 09:30:00-04')::timestamptz);
select pg_temp.reject_it($q$update donor_agenda_capacity set slot_minutes=60 where branch_id='e1000000-0000-0000-0000-000000000001'$q$,'configuración no puede exceder reservas existentes');
select pg_temp.check_it('agenda muestra citas y nombre del donante',(select count(*)=2 from vw_donor_appointment_agenda));
select pg_temp.check_it('coordinación identifica cita activa',(select active_visit_id='e4000000-0000-0000-0000-000000000001' from vw_donor_coordination where id='e3000000-0000-0000-0000-000000000001'));
insert into donor_contacts(donor_id,branch_id,channel,outcome,notes,contacted_at) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','LLAMADA','NO_DESEA','No desea donar por ahora',now()-interval '1 minute');
select pg_temp.check_it('último resultado de contacto disponible',(select last_contact_outcome='NO_DESEA' from vw_donor_coordination where id='e3000000-0000-0000-0000-000000000001'));
select pg_temp.check_it('preparación no genera donaciones',(select count(*)=1 from donations));
update donor_visits set status='CANCELADA' where id='e4000000-0000-0000-0000-000000000003';
select pg_temp.check_it('cancelar libera la cita activa',(select active_visit_id is null from vw_donor_coordination where id='e3000000-0000-0000-0000-000000000003'));
-- A reservation whose donor origin is hidden by RLS still consumes a slot.
reset role;insert into test_branches values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000002');
set role authenticated;
insert into donor_visits(donor_id,branch_id,starts_at) values('e3000000-0000-0000-0000-000000000004','e1000000-0000-0000-0000-000000000001',((current_date+90)::text||' 10:00:00-04')::timestamptz);
reset role;delete from test_branches where branch='e1000000-0000-0000-0000-000000000002';
set role authenticated;
select pg_temp.check_it('identidad de otra sucursal queda oculta',(select count(*)=0 from donor_visits where donor_id='e3000000-0000-0000-0000-000000000004'));
select pg_temp.reject_it($q$insert into donor_visits(donor_id,branch_id,starts_at) values('e3000000-0000-0000-0000-000000000003','e1000000-0000-0000-0000-000000000001',((current_date+90)::text||' 10:05:00-04')::timestamptz)$q$,'cupo oculto por RLS también bloquea sobrecupo');
select set_config('test.actor','e2000000-0000-0000-0000-000000000002',false);
update donor_agenda_capacity set capacity=4;select pg_temp.check_it('consulta no cambia cupos',(select capacity=1 from donor_agenda_capacity limit 1));
reset role;set role anon;
select pg_temp.reject_it($q$select * from operations_orders$q$,'anónimo no accede a pedidos');
select pg_temp.reject_it($q$select * from vw_donor_coordination$q$,'anónimo no accede a coordinación');
select pg_temp.reject_it($q$select * from vw_donor_appointment_agenda$q$,'anónimo no accede a agenda');
reset role;
